// Java equivalent of SupervisorDemo.kt: CompletableFutures are independent by default, like
// children of a supervisor. Nothing cancels the siblings, so each future handles its own failure.
package workbench.coroutines.l06;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class SupervisorDemoJava {
    static long started;
    static void log(String msg) { System.out.printf("%5d ms  %s%n", (System.nanoTime() - started) / 1_000_000, msg); }
    static void sleep(long ms) { try { Thread.sleep(ms); } catch (InterruptedException e) { Thread.currentThread().interrupt(); } }

    public static void main(String[] args) {
        started = System.nanoTime();
        try (ExecutorService pool = Executors.newVirtualThreadPerTaskExecutor()) {
            CompletableFuture<Void> email = CompletableFuture.runAsync(() -> { sleep(300); log("email sent"); }, pool);
            CompletableFuture<Void> sms = CompletableFuture.runAsync(() -> {
                sleep(50);
                throw new UncheckedIOException(new IOException("sms gateway down"));
            }, pool);
            CompletableFuture<Void> push = CompletableFuture.runAsync(() -> { sleep(100); log("push sent"); }, pool);
            // each failure is handled where it happens; the siblings never hear about it
            CompletableFuture<Void> smsHandled = sms.exceptionally(e -> { log("handled: " + e.getCause().getCause().getMessage()); return null; });
            CompletableFuture.allOf(email, smsHandled, push).join();
            log("all three settled");
        }
    }
}

sections.body:
Here is the most common wrong fix. A merchant webhook in a capture handler keeps cancelling its siblings when the merchant's server is down, so someone writes:

```kotlin
coroutineScope {
    launch(SupervisorJob()) { webhooks.post(event) }   // meant as "make this child supervised"
    launch { ledger.record(event) }
}
```

```java
// Java equivalent: hand the task to some other, longer-lived executor
try (var request = Executors.newVirtualThreadPerTaskExecutor()) {
    SHARED_POOL.submit(() -> webhooks.post(event));     // no longer part of this request
    request.submit(() -> ledger.record(event));
}
```

It reads like "a supervised child". It is something else. A `Job` in a builder's context replaces the parent, so the new coroutine becomes the child of that fresh `SupervisorJob`, which has no parent of its own. The coroutine has left the tree. `coroutineScope` doesn't wait for it, cancelling the request doesn't cancel it, and its failure goes to a handler or the uncaught exception handler instead of to the request. It is `GlobalScope` from lesson 3 of this track, spelled differently.

The builder docs say it plainly: passing a `Job` there breaks structured concurrency, and it doesn't throw "only for backward compatibility reasons". kotlinx.coroutines 1.11 goes further and deprecates the overload, so the compiler now warns: "Passing a Job to coroutine builders breaks structured concurrency, leading to hard-to-diagnose errors." The same rule applies to `async` and `withContext`. The one documented exception is `withContext(NonCancellable)` for cleanup, from lesson 5 of this track.

Put the supervisor where it belongs. Inside a function, wrap the children in `supervisorScope { }`. For background work, give the owning class a scope built with `SupervisorJob()` in its constructor, and launch into that scope. Then the work is supervised and still owned: the scope waits for it, counts it and cancels it on shutdown.

When you see `launch(SupervisorJob())`, `launch(Job())` or `async(SupervisorJob())` in a review, ask what the author wanted. Usually the answer is one of those two shapes.

code.src:
package workbench.coroutines.l06

import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.cancelAndJoin
import kotlinx.coroutines.delay
import kotlinx.coroutines.launch
import kotlinx.coroutines.runBlocking

private var since = 0L
private fun stamp(msg: String) = println("%5d ms  %s".format((System.nanoTime() - since) / 1_000_000, msg))

fun main() = runBlocking {
    since = System.nanoTime()
    val request = launch {
        // looks like "a supervised child". It is a child of a brand-new SupervisorJob instead,
        // so it has left the request's tree: nobody waits for it and nobody cancels it.
        launch(SupervisorJob()) {
            delay(300)
            stamp("trap child: still running, nobody cancelled me")
        }
        launch {
            try { delay(300); stamp("normal child: done") } finally { stamp("normal child: finally") }
        }
    }
    delay(100)
    request.cancelAndJoin()
    stamp("request cancelled and joined")
    delay(400)
    stamp("main done")
}

