class WebhookSender implements AutoCloseable {
    private final ExecutorService pool = Executors.newFixedThreadPool(8, r -> {
        Thread t = new Thread(r, "webhooks");
        // last resort for task failures, like a CoroutineExceptionHandler
        t.setUncaughtExceptionHandler((th, e) -> log.warn("webhook failed", e));
        return t;
    });

    void post(Event event) {
        pool.execute(() -> client.post(event));   // execute, not submit: failures reach the handler
    }

    @Override public void close() { pool.shutdownNow(); }
}

kotlin.src:
class WebhookSender(dispatcher: CoroutineDispatcher = Dispatchers.IO) {
    private val handler = CoroutineExceptionHandler { _, e -> log.warn("webhook failed", e) }

    // SupervisorJob: one failed post doesn't cancel the others or the scope
    private val scope = CoroutineScope(SupervisorJob() + dispatcher + handler)

    fun post(event: Event): Job =
        scope.launch { client.post(event) }       // a root child: failures reach the handler

    fun close() = scope.cancel()
}

