suspend fun captureAndNotify(cmd: Capture): Pair<CaptureResult, Boolean> = supervisorScope {
    val result = issuer.capture(cmd)
    ledger.record(result)
    // 4. waited for, but allowed to fail alone
    val hook = async { webhooks.post(result.toEvent()) }
    val delivered = try { hook.await(); true }
        catch (e: CancellationException) { throw e }
        catch (e: Exception) { false }
    result to delivered
}

